const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const root=path.join(__dirname,'..'),source=fs.readFileSync(path.join(root,'experience/cbse-study.js'),'utf8');
function fixture(raw){const values=new Map(raw===undefined?[]:[['peq_cbse_study_v1',raw]]),routes=[];const c={window:{addEventListener(){}},location:{hash:'',pathname:'/',search:''},localStorage:{getItem:k=>values.get(k)||null,setItem:(k,v)=>values.set(k,v)},go:(v,id)=>routes.push([v,id]),Landing:{show(){},pending:()=>true,visible:()=>false},Onboard:{},AppDesign:{afterView(){},init(){}},document:{},history:{replaceState(){}},Object,Number,String,Boolean,JSON,Math};vm.createContext(c);vm.runInContext(source,c);return {c,api:c.CbseStudy,values,routes};}
const profile={v:1,status:'ready',class:'11',goal:'foundations',minutes:'20',focus:'kinematics'};
test('Class numbers must be stored as the same string used by route and tab keys',()=>{assert.equal(fixture().api.validate({...profile,class:11}),null);});
test('CBSE profile permits only bounded preferences and never student identity',()=>{const f=fixture();const p=f.api.validate({...profile,name:'private',email:'private',score:99});assert.deepEqual(JSON.parse(JSON.stringify(p)),profile);for(const extra of [{v:2},{class:'8'},{class:'__proto__'},{goal:'constructor'},{minutes:90},{focus:'sound'},{status:'mastered'}])assert.equal(f.api.validate({...profile,...extra}),null);assert.equal(f.api.validate(null),null);});
test('Malformed and unavailable storage keep optional onboarding usable',()=>{for(const raw of ['{bad','null','[]','{}','"bad"']){const f=fixture(raw);assert.equal(f.api.read(),null);assert.equal(f.c.Landing.pending(),true);}const f=fixture('{}');f.c.localStorage.setItem=()=>{throw Error('blocked')};assert.equal(f.api.save(profile),false);assert.equal(f.api.read().class,'11');assert.equal(f.c.Landing.pending(),false);assert.equal(f.values.get('peq_cbse_study_v1'),'{}');});
test('Skipping is a distinct preference and leaves progress keys alone',()=>{const f=fixture();f.values.set('peq_notes','retain');f.values.set('peq_profile','legacy');f.api.save({v:1,status:'skipped'});assert.equal(f.api.read().status,'skipped');assert.equal(f.values.get('peq_notes'),'retain');assert.equal(f.values.get('peq_profile'),'legacy');assert.equal(f.values.size,3);});
test('Time and focus produce a real bounded plan; missing units stay gaps',()=>{const f=fixture();for(const minutes of ['10','20','30']){const p=f.api.plan({...profile,minutes,focus:'waves'});assert.equal(p.unit.id,'waves');assert.equal(p.resource.lessons[0],'shm');assert.equal(p.study+p.recall+p.check,Number(minutes));}const p=f.api.plan({...profile,focus:'measurements'});assert.equal(p.unit.lessons.length,0);assert.equal(p.resource.id,'kinematics');});
test('Current Class9 map does not substitute stagewide gravitation for taught units',()=>{const c=fixture().api.courses;assert.deepEqual(Array.from(c['9'].units,u=>u.id),['motion','forces','energy','sound','earth']);assert.match(c['9'].units.find(u=>u.id==='energy').title,/simple machines/);assert.match(c['9'].note,/advanced-level syllabus is not mapped/);assert.match(c['10'].note,/examination eligibility|Confirm examination/);});
test('Every linked concept exists; no heading is counted as a completed lesson',()=>{const html=fs.readFileSync(path.join(root,'index.html'),'utf8'),ids=new Set(Array.from(html.matchAll(/^\s*\{id:"([^"]+)",name:/gm),m=>m[1]));for(const course of Object.values(fixture().api.courses)){for(const u of course.units){assert.ok(u.gap.length>20);for(const id of u.lessons)assert.ok(ids.has(id),id);}assert.ok(course.source.startsWith('https://cbseacademic.nic.in/'));}assert.match(source,/not a completed CBSE course/);assert.match(source,/A suggested routine, not a mastery estimate/);});
test('Questionnaire is synchronous entry with native modal focus and no camera or account calls',()=>{assert.match(source,/dialog.showModal\(\);var gate=/);assert.match(source,/Landing.show=function\(\)\{if\(!read\(\)\)show\(true\)/);assert.match(source,/dialog.addEventListener\('cancel'/);assert.doesNotMatch(source,/getUserMedia|GAuth\.|fetch\(|XMLHttpRequest|peq_profile['"]/);assert.match(source,/if\(firstVisit&&initialDestination/);assert.match(source,/history.replaceState/);});
test('First-question markup precedes app markup and the large app script',()=>{const html=fs.readFileSync(path.join(root,'index.html'),'utf8'),early=fs.readFileSync(path.join(root,'experience/cbse-entry.html'),'utf8');assert.ok(html.indexOf('<!-- CBSE-ENTRY:START -->')<html.indexOf('<div class="app">'));assert.match(early,/gate.showModal\(\)/);assert.match(early,/window.__peqCbseEntry.next=true/);assert.match(source,/if\(early.next\)step=1/);});
test('Captured deep-link intent survives a shared-scene hash being consumed during boot',()=>{assert.match(source,/initialDestination=explicitDestination\(\)/);assert.match(source,/if\(firstVisit&&!initialDestination\)originalLandingShow\(\)/);assert.match(source,/p.status!=='ready'&&!initialDestination&&originalLandingPending/);});
test('Only new source slots extend the builder; established launch source remains untouched',()=>{const builder=fs.readFileSync(path.join(root,'.github/build-experience.js'),'utf8');assert.match(builder,/embed\('CBSE-STUDY','cbse-study.js','\/\* ===== INIT ===== \*\/'\)/);assert.match(builder,/'cbse-study.css'/);const html=fs.readFileSync(path.join(root,'index.html'),'utf8');assert.ok(html.indexOf('/* EXPERIENCE:CBSE-STUDY:START */')<html.indexOf('Me.streakInit(); renderSide();'));assert.equal((html.match(/\/\* EXPERIENCE:CBSE-STUDY:START \*\//g)||[]).length,1);});
